import re, subprocess, os, glob, sys

APP='/app'; PT='/tmp/ptest'; os.makedirs(PT, exist_ok=True)

# Preamble: everything in main.tex before \begin{document}
main=open(APP+'/main.tex').read()
preamble=main.split('\\begin{document}')[0]

def load_syn():
    d={}
    for line in open(APP+'/synonyms.txt'):
        w=[x.strip() for x in line.strip().split(',')]
        if w:
            d[w[0]]=w
    return d
SYN=load_syn()
KEYS=sorted(SYN.keys(), key=len, reverse=True)
PAT=re.compile(r'\b('+'|'.join(re.escape(k) for k in KEYS)+r')\b', re.IGNORECASE)

def paragraphs():
    lines=open(APP+'/input.tex.bak').read().split('\n')
    return [l for l in lines if l.strip()]

def overfulls(tex):
    open(PT+'/t.tex','w').write(tex)
    r=subprocess.run(['pdflatex','-interaction=nonstopmode','t.tex'],cwd=PT,
                     capture_output=True,text=True)
    log=(r.stdout+r.stderr).split('\n')
    res=[]
    for i,l in enumerate(log):
        m=re.search(r'Overfull \\hbox \(([^)]+?)\s*pt', l)
        if m:
            res.append((float(m.group(1)), log[i+1].strip() if i+1<len(log) else ''))
    for f in ['t.pdf','t.aux','t.log']:
        p=os.path.join(PT,f)
        if os.path.exists(p): os.remove(p)
    return res

def para_tex(p):
    return preamble+'\n\\begin{document}\n\n'+p+'\n\n\\end{document}\n'

def apply_map(text, m):
    def repl(mm):
        w=mm.group(0)
        if w.lower() in m:
            rep=m[w.lower()]
            if w[0].isupper(): rep=rep[0].upper()+rep[1:]
            return rep
        return w
    return PAT.sub(repl, text)

if __name__=='__main__':
    for idx,p in enumerate(paragraphs()):
        of=overfulls(para_tex(p))
        tot=sum(x for x,_ in of)
        tag='OVERFULL' if of else 'ok'
        print(f'P{idx+1}: {tag} total={tot:.3f}  #words={len(PAT.findall(p))}')
        for x,t in of:
            print(f'      {x:.3f}  ||  {t}')
