import re, subprocess, os
from parasolve import SYN, PAT, paragraphs, overfulls, para_tex, preamble, PT, APP
import copy

os.makedirs(PT, exist_ok=True)

def distinct_changeable(text):
    return set(PAT.findall(text))

def apply_map(text, m):
    def repl(mm):
        w=mm.group(0)
        if w.lower() in m:
            rep=m[w.lower()]
            if w[0].isupper(): rep=rep[0].upper()+rep[1:]
            return rep
        return w
    return PAT.sub(repl, text)

def cost_of(text):
    of=overfulls(para_tex(text))
    return sum(x for x,_ in of), of

def solve(para_idx, budget=400):
    orig=paragraphs()[para_idx-1]
    words=distinct_changeable(orig)
    # init: all-shortest (only words that have a shorter/equal synonym)
    init={}
    for W in words:
        cands=[s for s in SYN[W] if len(s)<=len(W) and s!=W]
        if cands:
            init[W.lower()]=min(cands,key=len)
    cur=apply_map(orig, init)
    tot,of=cost_of(cur)
    print(f'\n--- P{para_idx} start all-shortest overfull={tot:.3f} ({len(of)} lines)')
    it=0; evals=1; improved=True
    while tot>0 and it<12 and evals<budget:
        improved=False; best=None
        for W in sorted(words):
            cands=[s for s in SYN[W] if len(s)<=len(W) and s!=W]
            cands=[W]+cands  # allow original too
            for s in cands:
                m=copy.deepcopy(init); m[W.lower()]=s
                txt=apply_map(orig,m)
                t2,of2=cost_of(txt); evals+=1
                if best is None or t2<best[0]:
                    best=(t2,m,txt)
        if best and best[0]<tot:
            tot,init,cur=best[0],best[1],best[2]
            it+=1; improved=True
            print(f'   it{it} -> overfull={tot:.3f}  (changed: { {k:v for k,v in init.items() if v!=k} })')
        else:
            break
    tot_final,of_final=cost_of(cur)
    final_changed={k:v for k,v in init.items() if v!=k}
    print(f'   RESULT P{para_idx}: overfull={tot_final:.3f} ({len(of_final)} lines) evals={evals} changed={final_changed}')
    return final_changed, cur, tot_final

if __name__=='__main__':
    results={}
    for pi in [3,4,7,10]:
        ch,txt,tot=solve(pi)
        results[pi]=(ch,txt,tot)
    print('\n==== SUMMARY ====')
    for pi in [3,4,7,10]:
        print(f'P{pi}: overfull={results[pi][2]:.3f}')
    import pickle
    with open('/tmp/results.pkl','wb') as f:
        pickle.dump({pi:{'changed':results[pi][0],'text':results[pi][1]} for pi in results}, f)
